import {collectParticipants,assignParticipant} from './participants.mjs';
import {pickupGroups,pickupsHTML} from './pickups.mjs';
import {shareTrip,sharedFeedback,sharedPanel} from './shared-ui.mjs';
import {exportHTML,exportExcel,exportFilename} from './trip-export.mjs';
import {participantRole,setTravelMode,saveVehicleAssignments,vehicleForPerson,vehicleKey,validateAssignments} from './transport.mjs';
import {rosterRows,resetWithRoster,cachedRoster} from './roster.mjs';
import {extractDocument} from './document-reader.mjs';
import {csvRecords,normalize,pendingItems} from './core.mjs';
import {syncDetectedParticipants,removeParticipant} from './document-model.mjs';
import {renderDashboard} from './trip-dashboard.mjs';
import {createDocumentFeatures} from './document-ui.mjs';
const sessionResponse=await fetch('/api/me',{cache:'no-store'});if(!sessionResponse.ok){location.assign('/signin-with-chatgpt?return_to=%2F');await new Promise(()=>{});}const sessionUser=await sessionResponse.json();if(!sessionUser.admin){location.replace('/me');await new Promise(()=>{});}
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rosterTarget=null;
let dashboardFilter='all';
let db,state={trips:[]},selected=null,globalView='trips',tab='overview',submitAction=null,importKind='people',folderTarget=null,toastTimer;
const dbReady=new Promise((resolve,reject)=>{const r=indexedDB.open('equip-viatges-v0',1);r.onupgradeneeded=()=>{r.result.createObjectStore('data');r.result.createObjectStore('folders');};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)});
async function read(store,key){await dbReady;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function write(store,key,value){await dbReady;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function remove(store,key){return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){collectParticipants(state);await write('data','state',state);render();const t=trip();if(t?.shared){try{await shareTrip(t);await write('data','state',state)}catch(e){render();toast('Canvis guardats al navegador. '+e.message)}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5500)}
function fail(e){console.error(e);toast(e.name==='QuotaExceededError'?'Emmagatzematge ple. Prova amb una carpeta més petita.':e.message||'No s’ha pogut completar l’operació.')}
const trip=()=>state.trips.find(t=>t.id===selected),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('ca-ES',{day:'numeric',month:'short',year:'numeric'}):'Dates per confirmar';
const badge=s=>`<span class="status ${['Comprat','Fet','Reservat'].includes(s)?'done':s==='No cal'?'neutral':''}">${esc(s==='Comprat'?'OK · Comprat':s||'Pendent')}</span>`;
const sport=s=>`<span class="pill ${s==='Ciclisme'?'cycle':''}">${s==='Ciclisme'?'↗':'❄'} ${esc(s)}</span>`;
const empty=(title,description,button='')=>`<div class="empty"><div class="empty-icon">▤</div><h3>${title}</h3><p>${description}</p>${button}</div>`;
function render(){const t=trip();$('#allTrips').classList.toggle('active',globalView==='trips');$('#allParticipants').classList.toggle('active',globalView==='participants');if(!t&&globalView==='participants'){$('#crumb').textContent='Participants';renderParticipants();return;}$('#crumb').textContent=t?t.name:'Viatges';if(!t){selected=null;renderHome();return}renderTrip(t)}
function renderParticipants(){
 collectParticipants(state);
 $('#app').innerHTML=`<div class="page-head"><div><h1>Participants</h1><p>Una fitxa per persona. Assigna-la als viatges amb el desplegable.</p></div><div class="actions"><button class="button secondary" data-action="import-directory">Importar Excel</button><button class="button" data-action="new-directory-person">＋ Participant</button></div></div>${!state.trips.length?'<div class="notice">Crea un viatge per poder-hi assignar participants. <button class="text-button" data-action="new-trip">＋ Crear viatge</button></div>':''}${state.participants.length?`<label class="field directory-search">Buscar participant<input id="participantSearch" type="search" placeholder="Nom o email" autocomplete="off"></label><div class="table-wrap"><table><thead><tr><th>PARTICIPANT</th><th>VIATGES ASSIGNATS</th><th>ASSIGNAR A UN VIATGE</th><th></th></tr></thead><tbody>${state.participants.map(p=>{const assigned=state.trips.filter(t=>t.people.some(x=>x.participantId===p.id)),available=state.trips.filter(t=>!assigned.includes(t));return `<tr data-directory-row data-search="${esc((p.name+' '+p.email).toLowerCase())}"><td><strong>${esc(p.name)}</strong><small>${esc(p.email||'Email personal pendent')}</small><small>${esc(p.role)}</small></td><td><div class="assigned-trips">${assigned.length?assigned.map(t=>`<button class="trip-assignment" data-action="open-trip" data-id="${esc(t.id)}">${esc(t.name)} ↗</button>`).join(''):'<span class="muted">Sense viatge assignat</span>'}</div></td><td><label class="field"><span class="visually-hidden">Assignar ${esc(p.name)} a un viatge</span><select data-assign-participant="${esc(p.id)}" ${available.length?'':'disabled'}><option value="">${available.length?'Selecciona un viatge…':'Cap viatge disponible'}</option>${available.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}${t.start?' · '+date(t.start):''}</option>`).join('')}</select></label></td><td><button class="edit-button" data-action="edit-directory-person" data-id="${esc(p.id)}">Editar dades</button></td></tr>`}).join('')}</tbody></table></div><p id="directoryEmpty" hidden>No s’ha trobat cap participant.</p><p class="small muted">Assignar una persona a un altre viatge conserva les assignacions anteriors. Els vols, vehicles i notes es gestionen dins de cada viatge.</p>`:empty('Afegeix els participants de l’equip','Importa un Excel o crea una fitxa. Després selecciona el viatge de cada persona.')}`;
}
function directoryPersonForm(id){const person=state.participants?.find(p=>p.id===id)||{};modal(id?'Dades del participant':'Nou participant',`<div class="form-grid">${field('Nom i cognoms','name',person.name,'text',true,true)}${field('Email personal','email',person.email,'email')}${field('Telèfon','phone',person.phone,'tel')}${select('Rol','role',person.role||'Esportista',['Esportista','Tècnic','Fisio','Altres'])}${field('Origen','origin',person.origin)}</div><p class="small muted">Les dades personals s’actualitzen als viatges assignats. Els vols i les recollides es conserven.</p>`,async data=>{data.email=data.email.toLowerCase();if(data.email&&state.participants.some(p=>p.id!==id&&p.email.toLowerCase()===data.email))throw Error('Ja existeix un participant amb aquest email.');const changed=[];if(id){Object.assign(person,data);for(const t of state.trips){const members=t.people.filter(p=>p.participantId===id);for(const p of members)Object.assign(p,data);if(members.length)changed.push(t);}}else state.participants.push({id:uid(),...data});await persist();for(const t of changed)await syncDirectoryTrip(t);toast('Dades personals guardades.');});}
async function syncDirectoryTrip(t){if(!t.shared)return;try{await shareTrip(t)}catch(e){toast('Dades locals guardades. '+e.message)}await write('data','state',state);}
function renderHome(){$('#app').innerHTML=`<div class="page-head"><div><h1>Viatges</h1><p>Selecciona un viatge per gestionar-lo.</p></div><button class="button" data-action="new-trip">＋ Nou viatge</button></div>${state.trips.length?`<div class="grid">${state.trips.map(t=>`<button class="trip-card" data-action="open-trip" data-id="${t.id}"><div class="trip-top">${sport(t.sport)}<span>↗</span></div><div class="trip-content"><h3>${esc(t.name)}</h3><p>${esc(t.destination||'Destinació pendent')} · ${date(t.start)}</p></div><div class="trip-footer"><span>${t.people.length} participants · ${t.vehicles.length} vehicles</span></div></button>`).join('')}</div>`:empty('Comença amb un viatge','Crea’l, importa els participants i selecciona la carpeta.')}<details class="simple-details"><summary>Còpies i dades</summary><p class="small muted">La coordinació es guarda en aquest navegador. Els itineraris compartits es guarden al servidor.</p><div class="actions"><button class="button secondary" data-action="backup">Exportar còpia</button><button class="button secondary" data-action="restore">Restaurar còpia</button></div></details>`}
function renderTrip(t){const transportTab=['vehicles','pickups'].includes(tab);$('#app').innerHTML=`<button class="back" data-action="home">← Viatges</button><div class="page-head"><div><h1>${esc(t.name)}</h1><p>${esc(t.destination||'Destinació pendent')} · ${date(t.start)}${t.end?' — '+date(t.end):''}</p></div><div class="actions"><button class="button" data-action="share-trip">${t.shared?'Actualitzar portal':'Compartir viatge'}</button><button class="button secondary" data-action="export-trip">↓ Resum</button><details class="more-menu"><summary class="button secondary">Més ···</summary><div class="more-menu-items"><button data-action="edit-trip">Editar viatge</button><button data-action="access-settings">Accés dels esportistes</button><button data-action="shared-feedback">Confirmacions</button><a href="/me" target="_blank" rel="noopener">Portal de l’esportista ↗</a><button data-action="import-roster">Canviar Excel de participants</button><button data-action="reset-roster">Reiniciar amb l’Excel</button><button data-action="backup">Exportar còpia de seguretat</button></div></details></div></div>${t.sharedError?`<div class="notice">${esc(t.sharedError)}</div>`:''}<nav class="tabs" aria-label="Seccions del viatge">${[['overview','Preparació'],['details','Dades del viatge'],['people','Participants'],['files','Documents i vols'],['vehicles','Vehicles i recollides']].map(([key,label])=>`<button class="tab ${(key==='vehicles'?transportTab:tab===key)?'active':''}" data-action="tab" data-id="${key}" aria-current="${(key==='vehicles'?transportTab:tab===key)?'page':'false'}">${label}</button>`).join('')}</nav><div id="tripContent">${tab==='overview'?overview(t):tab==='details'?tripDetails(t):tab==='people'?people(t):transportTab?`<div class="transport-switch"><button class="button ${tab==='pickups'?'secondary':''}" data-action="tab" data-id="vehicles">Vehicles</button><button class="button ${tab==='vehicles'?'secondary':''}" data-action="tab" data-id="pickups">Recollides</button></div>${tab==='pickups'?pickupsHTML(t,esc):vehicles(t)}`:files(t)}</div>`}
function folderPanel(t){return `<div class="folder-panel"><div class="folder-icon">▣</div><div><h3>${esc(t.folder?.name||'Vincula la carpeta del viatge')}</h3><p>${t.folder?`${t.files.length} documents · ${t.folder.mode==='handle'?'Lectura amb permís':'Còpia local al navegador'}`:'Selecciona una carpeta del teu ordinador per tenir els documents a mà.'}</p>${t.folder?`<p>Última lectura: ${new Date(t.folder.updated).toLocaleString('ca-ES')}</p>`:''}</div><div class="actions">${t.folder?'<button class="button lime" data-action="refresh-folder">↻ Actualitzar</button>':''}<button class="button ${t.folder?'secondary':'lime'}" data-action="link-folder">${t.folder?'Canviar carpeta':'Vincular carpeta'}</button></div></div>`}
function rosterPanel(t){return `<div class="notice"><strong>1. Excel de participants → 2. Carpeta de documents</strong><p>${t.rosterSource?esc(t.rosterSource)+' · '+t.people.length+' participants':'Importa l’Excel amb la llista oficial. Després selecciona la carpeta per associar les reserves.'}</p><div class="actions"><button class="button" data-action="import-roster">Importar Excel de participants</button><button class="button secondary" data-action="reset-roster">Reiniciar amb l’Excel llegit</button></div></div>`}
function rosterPreview(t,rows,source){modal('Reiniciar amb '+rows.length+' participants',`<p>Es substituirà la llista d’aquest viatge pels participants de <strong>${esc(source)}</strong>.</p><div class="notice">S’esborraran les associacions, els estats de bitllet i check-in i la vinculació amb la carpeta. Després podràs seleccionar la carpeta de nou. Els documents originals no es modifiquen.</div><div class="csv-preview"><ul>${rows.map(p=>`<li>${esc(p.name)}${p.role?' · '+esc(p.role):''}</li>`).join('')}</ul></div>`,async()=>{const draft=resetWithRoster(t,rows,source),next={...state,trips:state.trips.map(x=>x.id===t.id?draft:x)};await new Promise((resolve,reject)=>{const tx=db.transaction(['data','folders'],'readwrite');tx.objectStore('data').put(t,'before-roster-reset:'+t.id);tx.objectStore('data').put(next,'state');tx.objectStore('folders').delete(t.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next;tab='overview';dashboardFilter='all';render();if(draft.shared){try{await shareTrip(draft);await write('data','state',state)}catch(e){toast('Reinici local guardat; falta actualitzar l’espai compartit. '+e.message);return}}toast(rows.length+' participants preparats. Ara selecciona la carpeta dels documents.')},'Reiniciar i posar els '+rows.length+' participants')}
function tripDetails(t){return `<div class="section-head"><div><h2>Dades del viatge</h2><p>Completa les dates, l’allotjament i el contacte de coordinació.</p></div><button class="button" data-action="edit-trip">Editar dades</button></div><div class="admin-detail-grid">${[['Viatge',[['Nom',t.name],['Equip',t.sport],['Destinació',t.destination],['Sortida',t.start?date(t.start):''],['Tornada',t.end?date(t.end):'']]],['Allotjament i contacte',[['Allotjament',t.hotel],['Responsable',t.coordinator],['Telèfon de coordinació',t.phone]]]].map(([title,rows])=>`<section class="panel"><h3>${title}</h3><dl class="detail-list">${rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${value?esc(value):'<span class="admin-missing">Pendent de completar</span>'}</dd></div>`).join('')}</dl></section>`).join('')}</div><section class="panel"><h3>Notes internes de coordinació</h3><p style="white-space:pre-wrap">${esc(t.notes||'Sense notes internes.')}</p><p class="small muted">Les indicacions personals per a cada esportista s’editen a la seva fitxa.</p></section>`}
function overview(t){
 const missing=[['destination','destinació'],['start','sortida'],['end','tornada'],['hotel','allotjament'],['coordinator','responsable'],['phone','telèfon']].filter(([key])=>!t[key]).map(([,label])=>label);
 const emails=t.people.filter(p=>!p.email).length,pending=documents.pending(t);
 const transportMissing=t.people.filter(p=>['Anada','Tornada'].some(d=>{const v=vehicleForPerson(t,p,d);return !v||!v.driver||!v.phone||!v.pickupLocation||!v.pickupTime})).length;
 const steps=[
 ['Dades del viatge',missing.length?'Falta: '+missing.join(', '):'Dates, allotjament i contacte completats.',!missing.length,'tab','details','Completar dades'],
 ['Participants',t.people.length?`${t.people.length} participants · ${emails?emails+' sense email personal':'emails informats'}`:'Importa la llista oficial amb noms i emails personals.',!!t.people.length&&!emails,t.people.length?'tab':'import-roster',t.people.length?'people':'',t.people.length?'Revisar participants':'Importar Excel'],
 ['Documents i vols',t.files.length?`${t.files.length} documents · ${pending} pendents de revisió`:'Selecciona la carpeta amb bitllets i reserves.',!!t.files.length&&!pending,'tab','files',t.files.length?'Revisar documents':'Afegir documents'],
 ['Vehicles i recollides',t.people.length?`${t.vehicles.length} vehicles · ${transportMissing} participants amb transport o contacte incomplet`:'Indica els conductors, telèfons, punts i hores de recollida.',!!t.people.length&&!transportMissing,'tab','vehicles','Organitzar transports'],
 ['Accés dels esportistes',t.shared?'Viatge compartit. Consulta els accessos i les confirmacions.':'Revisa els emails personals abans de compartir el viatge.',!!t.shared,'access-settings','','Revisar accés']
 ];
 return `<section class="admin-preparation"><div class="section-head"><div><h2>Prepara el viatge</h2><p>Completa cada apartat. Pots tornar-hi i corregir les dades en qualsevol moment.</p></div><span class="pill">${steps.filter(s=>s[2]).length} de ${steps.length} apartats completats</span></div><div class="preparation-steps">${steps.map(([title,description,done,action,id,label],i)=>`<section class="preparation-step ${done?'is-complete':''}"><span class="step-number">${done?'✓':i+1}</span><div><h3>${title}</h3><p>${esc(description)}</p></div><button class="button secondary" data-action="${action}" data-id="${id}">${label}</button></section>`).join('')}</div></section>${t.people.length?`<div class="section-head"><h2>Seguiment dels participants</h2><button class="button secondary" data-action="shared-feedback">Veure confirmacions</button></div>${renderDashboard(t,dashboardFilter,esc)}`:''}`;
}
function people(t){return `<div class="section-head"><h2>${t.people.length} participants</h2><button class="button" data-action="directory">Assignar participants</button><button class="button secondary" data-action="import-roster">${t.people.length?'Canviar llista d’Excel':'Importar Excel'}</button></div>${t.people.length?`<div class="table-wrap"><table class="compact-people"><thead><tr><th>PARTICIPANT</th><th>BITLLET</th><th>CHECK-IN</th><th>VEHICLE</th><th></th></tr></thead><tbody>${t.people.map(p=>`<tr><td><button class="person-name text-button" data-action="participant-itinerary" data-id="${p.id}">${esc(p.name)}</button><small>${esc(participantRole(p.role))} · ${esc(p.travelMode||'Avió')}</small><small class="${p.email?'':'admin-missing'}">${esc(p.email||'Falta email personal')}</small></td><td>${badge(p.ticket)}</td><td><button class="text-button" data-action="person-checkin" data-id="${p.id}" aria-label="Check-in de ${esc(p.name)}">${badge(p.checkin)} ↗</button></td><td>${['Anada','Tornada'].map(d=>{const v=vehicleForPerson(t,p,d);return `<small>${d}: ${esc(v?.name||'Sense assignar')}</small>`}).join('')}</td><td><button class="edit-button" data-action="edit-person" data-id="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Importa la llista de participants','Fes servir l’Excel amb els noms i emails personals.')}<p class="muted small">Prem el nom per veure l’itinerari complet.</p>`}
function vehicles(t){return `<div class="section-head"><h2>Transports</h2><div class="actions"><details class="simple-details inline-details"><summary>Importar vehicles</summary><button class="text-button" data-action="template" data-id="vehicles">Plantilla CSV</button><button class="text-button" data-action="import" data-id="vehicles">Importar CSV</button></details><button class="button" data-action="new-vehicle">＋ Vehicle</button></div></div>${t.vehicles.length?`<div class="grid">${t.vehicles.map(v=>{const ps=t.people.filter(p=>p[vehicleKey(v.direction)]===v.id);return `<section class="panel"><div class="section-head" style="margin-top:0"><h3>${esc(v.name)}</h3><span class="pill">${esc(v.direction)}</span></div><dl class="detail-list"><div><dt>Conductor</dt><dd>${esc(v.driver||'Per assignar')}</dd></div><div><dt>Telèfon</dt><dd>${esc(v.phone||'Sense indicar')}</dd></div><div><dt>Sortida</dt><dd>${esc(v.origin||'Per confirmar')}</dd></div><div><dt>Hora</dt><dd>${esc(v.departure||'Per confirmar')}</dd></div><div><dt>Places per a passatgers</dt><dd>${v.seats||'Sense indicar'}</dd></div><div><dt>Aparcament</dt><dd>${esc(v.parking||'Sense indicar')}</dd></div></dl><p class="small"><strong>Passatgers assignats:</strong> ${ps.length?ps.map(p=>esc(p.name)).join(', '):'Cap'}</p>${v.passengers?`<p class="small"><strong>Passatgers indicats al CSV:</strong> ${esc(v.passengers)}</p>`:''}${v.pickupLocation||v.pickupTime?`<p><strong>Recollida:</strong> ${esc(v.pickupLocation||'Lloc pendent')} · ${esc(v.pickupTime||'Hora pendent')}</p>`:''}${v.notes?`<p class="small muted">${esc(v.notes)}</p>`:''}<button class="edit-button" data-action="edit-vehicle" data-id="${v.id}">Editar transport</button></section>`}).join('')}</div>`:empty('Cada trajecte, ben organitzat','Crea un vehicle per trajecte: anada o tornada. Indica el conductor, la sortida, l’hora i les places.','<button class="button" data-action="new-vehicle">＋ Afegir vehicle</button>')}`}
function files(t){return `<section class="panel import-guide"><h2>Importa la informació dels documents</h2><p><strong>1.</strong> Importa l’Excel de participants. <strong>2.</strong> Selecciona la carpeta. <strong>3.</strong> Revisa i confirma les dades detectades.</p><p class="muted">Els PDF, Excel, CSV i imatges compatibles poden aportar vols, horaris, localitzadors i emails de compra. Completa l’allotjament, els conductors i les recollides als seus apartats.</p>${!t.people.length?'<button class="button" data-action="import-roster">Importar participants</button>':''}</section>${folderPanel(t)}${documents.panel(t)}<div class="notice">${t.folder?.mode==='handle'?'La carpeta es rellegeix amb «Actualitzar».':'Torna a seleccionar la carpeta per actualitzar-ne la còpia local.'} Els fitxers nous es llegeixen automàticament. No s’envia cap document a un servidor.</div>${t.files.length?`<div class="table-wrap"><table><thead><tr><th>DOCUMENT</th><th>LECTURA / PERSONES</th><th>MIDA</th><th></th></tr></thead><tbody>${t.files.map((f,i)=>`<tr><td class="file-path"><strong>${esc(f.name)}</strong><small>${esc(f.path)}</small></td><td>${documents.status(t,f)}</td><td class="nowrap">${formatSize(f.size)}</td><td><div class="row-links"><button class="edit-button" data-action="review-document" data-id="${esc(f.path)}">Revisar / associar</button><button class="edit-button" data-action="download-file" data-id="${i}">Descarregar</button>${/\.(csv|tsv)$/i.test(f.name)?`<button class="edit-button" data-action="import-file" data-id="${i}">Importar dades</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Els documents del viatge','Vincula una carpeta. Llegirem els noms i els trajectes per proposar-te a qui correspon cada document.')}`}

function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function field(label,key,value='',type='text',full=false,required=false){return `<label class="field ${full?'full':''}">${label}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''}></label>`}
function select(label,key,value,options){return `<label class="field">${label}<select name="${key}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
function notes(value){return `<label class="field full">Notes<textarea name="notes">${esc(value||'')}</textarea></label>`}
function modal(title,html,fn,label='Guardar'){$('#modal').classList.remove('document-modal');submitAction=fn;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#submitModal').textContent=label;$('#modal').showModal()}
function tripForm(edit=false){const t=edit?trip():{};modal(edit?'Editar viatge':'Nou viatge',`<div class="form-grid"><h3 class="form-section-title">Destinació i dates</h3>${field('Nom del viatge','name',t.name,'text',true,true)}${select('Equip','sport',t.sport||'Esquí',['Esquí','Ciclisme'])}${field('Destinació','destination',t.destination)}${field('Data de sortida','start',t.start,'date')}${field('Data de tornada','end',t.end,'date')}<h3 class="form-section-title">Contacte de coordinació</h3>${field('Responsable','coordinator',t.coordinator)}${field('Telèfon','phone',t.phone,'tel')}<h3 class="form-section-title">Allotjament</h3>${field('Nom i adreça de l’allotjament','hotel',t.hotel,'text',true)}<label class="field full">Notes internes de coordinació<textarea name="notes">${esc(t.notes||'')}</textarea></label></div>`,async data=>{if(data.start&&data.end&&data.end<data.start)throw Error('La tornada no pot ser anterior a la sortida.');if(edit)Object.assign(t,data);else{const n={...data,id:uid(),rosterMode:'excel',people:[],vehicles:[],files:[],folder:null};state.trips.push(n);selected=n.id;globalView='trips';tab='overview'}await persist();toast(edit?'Viatge actualitzat':'Viatge creat. Ja pots vincular-hi una carpeta.')})}
function personForm(id){const t=trip();if(!id&&t.rosterMode==='excel'){handlers['import-roster']();return}const p=t.people.find(p=>p.id===id)||{};modal(id?'Editar participant':'Nou participant',`<div class="form-grid">${field('Nom i cognoms','name',p.name,'text',true,true)}${select('Rol a l’equip','role',participantRole(p.role),['Esportista','Tècnic','Fisio','Altres'])}${select('Com viatja','travelMode',p.travelMode||'Avió',['Avió','Cotxe','Per decidir'])}${field('Email personal · accés al viatge','email',p.email,'email')}${field('Telèfon','phone',p.phone,'tel')}${field('Origen','origin',p.origin)}${select('Bitllet','ticket',p.ticket||'Pendent',['Pendent','Comprat','No cal'])}${select('Check-in','checkin',p.checkin||'Pendent',['Pendent','Fet','No cal'])}${field('Arribada · dia, hora i lloc','arrival',p.arrival,'text',true)}${select('Vehicle assignat','vehicle',p.vehicle||'',[['','Sense assignar'],...t.vehicles.filter(v=>v.direction!=='Tornada').map(v=>[v.id,`${v.name} · ${v.direction}`])])}${select('Vehicle de tornada','returnVehicle',p.returnVehicle||'',[['','Sense assignar'],...t.vehicles.filter(v=>v.direction==='Tornada').map(v=>[v.id,v.name])])}${field('Recollida · persona i lloc','pickup',p.pickup)}${field('Aparcament','parking',p.parking,'text',true)}${notes(p.notes)}</div>${id?documents.journeySummary(t,p)+documents.personSummary(t,p)+`<button type="button" class="button secondary" data-action="participant-itinerary" data-id="${p.id}">Veure itinerari individual</button>`:''}${id?'<button type="button" class="text-button error" data-action="delete-person" data-id="'+id+'">Eliminar participant</button>':''}`,async data=>{if(id){const check=structuredClone(t);Object.assign(check.people.find(x=>x.id===id),data);validateAssignments(check);if(data.ticket!==p.ticket)p.ticketSource='manual';const mode=data.travelMode;delete data.travelMode;Object.assign(p,data);setTravelMode(p,mode)}else t.people.push({...data,id:uid()});await persist();toast('Participant guardat')})}
function vehicleForm(id){const t=trip(),v=t.vehicles.find(v=>v.id===id)||{};modal(id?'Editar transport':'Nou transport',`<div class="form-grid">${field('Vehicle · nom o matrícula','name',v.name,'text',false,true)}${select('Trajecte','direction',v.direction||'Anada',['Anada','Tornada'])}${select('Conductor · participant','driverId',v.driverId||'',[['','Conductor extern'],...t.people.map(p=>[p.id,p.name+' · '+participantRole(p.role)])])}${field('Nom del conductor extern','driver',v.driver)}${field('Telèfon del conductor','phone',v.phone,'tel')}${field('Punt de sortida','origin',v.origin)}${field('Dia i hora de sortida','departure',v.departure)}${field('Places per a passatgers (sense conductor)','seats',v.seats||'','number')}${field('Aparcament / reserva','parking',v.parking)}${field('Aeroport / punt de recollida','pickupLocation',v.pickupLocation)}${field('Hora de recollida','pickupTime',v.pickupTime)}${field('Passatgers indicats / anotacions','passengers',v.passengers,'text',true)}<fieldset class="field full"><legend>Assignar passatgers a aquest vehicle</legend>${t.people.map(p=>`<label class="check-label"><input type="checkbox" name="passenger_${p.id}" ${p[vehicleKey(v.direction)]===v.id&&v.id?'checked':''}>${esc(p.name)} · ${esc(participantRole(p.role))}</label>`).join('')}</fieldset>${notes(v.notes)}</div><p class="small muted">Selecciona els passatgers d’aquest trajecte. El conductor viatja amb cotxe i no ocupa una plaça de passatger. Les assignacions d’anada i tornada són independents.</p>${id?'<button type="button" class="text-button error" data-action="delete-vehicle" data-id="'+id+'">Eliminar vehicle</button>':''}`,async data=>{data.seats=Number(data.seats)||0;const ids=Object.keys(data).filter(k=>k.startsWith('passenger_')).map(k=>k.slice(10));for(const k of Object.keys(data))if(k.startsWith('passenger_'))delete data[k];const draft=saveVehicleAssignments(t,{...data,id:id||uid()},ids);await saveTrip(draft);toast('Transport i passatgers assignats')})}
async function scan(handle){const out=[];async function walk(dir,prefix=''){for await(const [name,entry]of dir.entries()){if(name.startsWith('.'))continue;const path=prefix+name;if(entry.kind==='directory')await walk(entry,path+'/');else{if(out.length>=2000)throw Error('La carpeta supera els 2.000 fitxers. Selecciona una carpeta específica del viatge.');const f=await entry.getFile();out.push({name,path,size:f.size,modified:f.lastModified})}}}await walk(handle);return out.sort((a,b)=>a.path.localeCompare(b.path))}
async function linkFolder(){const t=trip();if(!t.people.length){toast('Importa primer l’Excel de participants.');return}if(!window.showDirectoryPicker){folderTarget=t.id;$('#folderInput').click();return}try{const handle=await window.showDirectoryPicker({mode:'read'});toast('Llegint la carpeta…');const list=await scan(handle);await write('folders',t.id,{handle});t.folder={name:handle.name,mode:'handle',updated:Date.now()};t.files=list;await persist();await documents.analyze(t)}catch(e){if(e.name!=='AbortError'){if(e.name==='SecurityError'){folderTarget=t.id;$('#folderInput').click()}else fail(e)}}}
async function refreshFolder(){const t=trip();if(!t.folder||t.folder.mode!=='handle'){folderTarget=t.id;$('#folderInput').click();return}const saved=await read('folders',t.id);if(!saved?.handle){toast('Torna a seleccionar la carpeta per recuperar l’accés.');return linkFolder()}if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');toast('Actualitzant documents…');const list=await scan(saved.handle);t.files=list;t.folder.updated=Date.now();await persist();await documents.analyze(t)}
async function localFile(t,index){const meta=t.files[index],saved=await read('folders',t.id);if(!saved)throw Error('Torna a vincular la carpeta per accedir als documents.');if(saved.handle){if(await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís per llegir el document.');let h=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))h=await h.getDirectoryHandle(part);return await(await h.getFileHandle(parts.at(-1))).getFile()}const f=saved.files?.find(f=>f.path===meta.path)?.file;if(!f)throw Error('Document no disponible. Actualitza la carpeta.');return f}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function template(kind){const content=kind==='people'?'Nom;Telefon;Origen;Arribada;Bitllet;Check-in;Recollida;Aparcament;Notes\r\nPersona exemple;600000000;Girona;Divendres 14:30 - Aeroport;Pendent;Pendent;;;\r\n':'Vehicle;Conductor;Telefon;Origen;Hora;Trajecte;Places;Passatgers;Aparcament;Notes\r\nFurgoneta 1;Conductor exemple;600000000;Girona;Divendres 08:00;Anada;7;;Pendent;Espai per al material\r\n';download(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}),`plantilla-${kind==='people'?'participants':'transports'}.csv`)}
function importPreview(text,kind){const records=csvRecords(text,kind),t=trip(),keys=Object.keys(records[0]);if(records.length>2000)throw Error('Importa un màxim de 2.000 files cada vegada.');modal(`Importar ${kind==='people'?'participants':'transports'}`,`<p>${records.length} fitxes detectades. Revisa les dades abans de continuar.</p><div class="csv-preview table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${records.slice(0,20).map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${records.length>20?'<p class="small">Es mostren les primeres 20 files.</p>':''}<div class="notice">S’afegiran només noms nous. Si el nom ja existeix, se saltarà la fila per conservar les teves correccions. Els passatgers d’un CSV de transports es guarden com a anotació.</div>`,async()=>{const list=kind==='people'?t.people:t.vehicles,known=new Set(list.map(x=>normalize(x.name)));let added=0;for(const r of records){if(known.has(normalize(r.name)))continue;list.push({...r,id:uid(),...(kind==='people'?{vehicle:''}:{})});known.add(normalize(r.name));added++}await persist();toast(`${added} fitxes afegides · ${records.length-added} duplicades omeses`)},'Confirmar importació')}
function backup(){download(new Blob([JSON.stringify({format:'equip-v0',exportedAt:new Date().toISOString(),trips:state.trips,participants:state.participants||[]},null,2)],{type:'application/json'}),'equip-viatges-copia.json');toast('Còpia exportada. Els documents originals no s’inclouen.')}
